="681" alt="" loading="lazy" decoding="async"><span class="town-in"><span class="town-t">Rock Springs</span><span class="town-c">Sweetwater County</span></span></a><a class="town rv" href="/where-we-work/sheridan/"><img src="/assets/img/photos/barns-snow.webp" srcset="/assets/img/photos/barns-snow-640.webp 640w, /assets/img/photos/barns-snow.webp 1024w" sizes="(max-width:700px) 50vw, 25vw" width="1024" height="770" alt="" loading="lazy" decoding="async"><span class="town-in"><span class="town-t">Sheridan</span><span class="town-c">Sheridan County</span></span></a><a class="town rv" href="/where-we-work/green-river/"><img src="/assets/img/photos/green-river-island.webp" srcset="/assets/img/photos/green-river-island-640.webp 640w, /assets/img/photos/green-river-island.webp 1200w" sizes="(max-width:700px) 50vw, 25vw" width="1200" height="900" alt="" loading="lazy" decoding="async"><span class="town-in"><span class="town-t">Green River</span><span class="town-c">Sweetwater County</span></span></a><a class="town rv" href="/where-we-work/evanston/"><img src="/assets/img/photos/uinta-wind-turbines.webp" srcset="/assets/img/photos/uinta-wind-turbines-640.webp 640w, /assets/img/photos/uinta-wind-turbines.webp 1024w" sizes="(max-width:700px) 50vw, 25vw" width="1024" height="708" alt="" loading="lazy" decoding="async"><span class="town-in"><span class="town-t">Evanston</span><span class="town-c">Uinta County</span></span></a><a class="town rv" href="/where-we-work/riverton/"><img src="/assets/img/photos/riverton-theater.webp" srcset="/assets/img/photos/riverton-theater-640.webp 640w, /assets/img/photos/riverton-theater.webp 1200w" sizes="(max-width:700px) 50vw, 25vw" width="1200" height="800" alt="" loading="lazy" decoding="async"><span class="town-in"><span class="town-t">Riverton</span><span class="town-c">Fremont County</span></span></a><a class="town rv" href="/where-we-work/jackson/"><img src="/assets/img/photos/jackson-downtown.webp" srcset="/assets/img/photos/jackson-do